    18	
    19	CREATE TABLE reservations (
    20	    id          bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    21	    room_number integer NOT NULL REFERENCES rooms (number),
    22	    guest_name  text NOT NULL,
    23	    guest_email text NOT NULL,
    24	    guest_cpf   text NOT NULL,
    25	    check_in    date NOT NULL,
    26	    check_out   date NOT NULL,
    27	    guests      integer NOT NULL CHECK (guests >= 1),
    28	    rate_plan   text NOT NULL,
    29	    nights      integer NOT NULL,
    30	    subtotal    numeric(10, 2) NOT NULL,
